const allowed = {
  avatars: {
    table: 'avatar_catalog',
    keyColumns: ['avatar'],
    columns: ['avatar', 'avatar_short', 'display_name', 'avatar_kind', 'description', 'notes'],
    defaults: {
      avatar_kind: 'influencer'
    }
  },
  scenes: {
    table: 'scene_catalog',
    keyColumns: ['avatar', 'scene'],
    columns: ['avatar', 'scene', 'display_name', 'description', 'notes'],
    defaults: {}
  },
  assetTypes: {
    table: 'asset_type_catalog',
    keyColumns: ['asset_type'],
    columns: ['asset_type', 'display_name', 'description', 'notes'],
    defaults: {}
  },
  workflows: {
    table: 'generation_workflow_catalog',
    keyColumns: ['workflow'],
    columns: ['workflow', 'display_name', 'description', 'notes'],
    defaults: {}
  },
  models: {
    table: 'generation_model_catalog',
    keyColumns: ['model'],
    columns: ['model', 'display_name', 'provider', 'description', 'notes'],
    defaults: {}
  }
};

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

function snakePayload(body) {
  return {
    avatar: body.avatar,
    avatar_short: body.avatarShort ?? body.avatar_short,
    display_name: body.displayName ?? body.display_name,
    avatar_kind: body.avatarKind ?? body.avatar_kind,
    description: body.description,
    notes: body.notes,

    scene: body.scene,
    asset_type: body.assetType ?? body.asset_type,
    workflow: body.workflow,
    model: body.model,
    provider: body.provider
  };
}

const body = $json.body || {};
const catalog = body.catalog ?? body.catalogType;
const def = allowed[catalog];

if (!def) {
  throw new Error(`Invalid catalog '${catalog}'. Allowed: ${Object.keys(allowed).join(', ')}`);
}

const payload = { ...def.defaults, ...snakePayload(body) };

for (const key of def.keyColumns) {
  if (!payload[key]) {
    throw new Error(`Missing required key '${key}'`);
  }
}

if (!payload.display_name) {
  payload.display_name = payload[def.keyColumns[def.keyColumns.length - 1]];
}

const cols = def.columns;
const values = cols.map(c => sql(payload[c]));

const updateSet = cols
  .filter(c => !def.keyColumns.includes(c))
  .map(c => `${c} = EXCLUDED.${c}`)
  .concat([
    'is_enabled = true',
    catalog === 'scenes' ? 'is_active = true' : null,
    'disabled_at = NULL',
    'disabled_reason = NULL',
    'updated_at = now()'
  ])
  .filter(Boolean)
  .join(', ');

const conflictColumns = def.keyColumns.join(', ');

const query = `
INSERT INTO ${def.table} (${cols.join(', ')}, is_enabled${catalog === 'scenes' ? ', is_active' : ''})
VALUES (${values.join(', ')}, true${catalog === 'scenes' ? ', true' : ''})
ON CONFLICT (${conflictColumns})
DO UPDATE SET ${updateSet}
RETURNING *;
`;

return { json: { query, catalog, table: def.table, keyColumns: def.keyColumns } };

const items = $input.all();

return [{
  json: {
    ok: true,
    count: items.length,
    item: items.length ? items[0].json : null
  }
}];
